basic.code:
// Every document of a collection: an empty filter
{"collection": "categories", "find": {}}

// Only the customers who live in Madrid
{"collection": "customers", "find": {"city": "Madrid"}}

// One document by its _id
{"collection": "products", "find": {"_id": 5}}

// All the customers, in _id order
{"collection": "customers", "find": {}, "sort": {"_id": 1}}

// Inclusion: only name and price (_id comes along)
{"collection": "products", "find": {"category_id": 2},
 "projection": {"name": 1, "price": 1}}

// Exclusion: everything except tags and active
{"collection": "products", "find": {"category_id": 3},
 "projection": {"tags": 0, "active": 0}}

// Three fields and no _id
{"collection": "products", "find": {},
 "projection": {"_id": 0, "name": 1, "price": 1, "stock": 1},
 "sort": {"name": 1}}

// Cheaper than 2 euros
{"collection": "products", "find": {"price": {"$lt": 2}},
 "projection": {"name": 1, "price": 1}, "sort": {"price": 1}}

// Out of stock, and everything except Bakery
{"collection": "products", "find": {"stock": {"$eq": 0}},
 "projection": {"name": 1, "stock": 1}}
{"collection": "products", "find": {"category_id": {"$ne": 1}},
 "projection": {"name": 1, "category_id": 1}, "sort": {"_id": 1}}

// A range: two operators on the same field
{"collection": "products",
 "find": {"price": {"$gte": 2, "$lte": 4}, "stock": {"$gt": 0}},
 "projection": {"_id": 0, "name": 1, "price": 1, "stock": 1},
 "sort": {"price": 1}}

// $in: the status is one of the list
{"collection": "orders", "find": {"status": {"$in": ["paid", "new"]}},
 "projection": {"status": 1, "total": 1}, "sort": {"_id": 1}}

// $nin: none of the list
{"collection": "customers", "find": {"city": {"$nin": ["Madrid", "Seville"]}},
 "projection": {"name": 1, "city": 1}, "sort": {"_id": 1}}

// Several keys in one filter are an implicit $and
{"collection": "products", "find": {"category_id": 4, "active": true},
 "projection": {"name": 1}, "sort": {"_id": 1}}

// $or: any of the conditions
{"collection": "products",
 "find": {"$or": [{"stock": 0}, {"price": {"$gt": 5}}]},
 "projection": {"_id": 0, "name": 1, "price": 1, "stock": 1},
 "sort": {"price": -1}}

// Names that start with "M"
{"collection": "customers", "find": {"name": {"$regex": "^M"}},
 "projection": {"name": 1}}

// "bread" anywhere, ignoring case
{"collection": "products",
 "find": {"name": {"$regex": "BREAD", "$options": "i"}},
 "projection": {"name": 1}}

// Names with a digit in them
{"collection": "products", "find": {"name": {"$regex": "\\d"}},
 "projection": {"name": 1}, "sort": {"_id": 1}}

// Customers with an e-mail at example.com, by name
{"collection": "customers",
 "find": {"email": {"$regex": "@example\\.com$"}},
 "projection": {"_id": 0, "name": 1, "email": 1},
 "sort": {"name": 1}}

// Review 5 has no comment: the grid shows it empty
{"collection": "reviews", "find": {},
 "projection": {"product_id": 1, "rating": 1, "comment": 1},
 "sort": {"_id": 1}}

// null matches a field set to null... and a missing one
{"collection": "employees", "find": {"manager_id": null},
 "projection": {"name": 1, "manager_id": 1}}
{"collection": "reviews", "find": {"comment": null},
 "projection": {"rating": 1}}

// $exists asks only whether the field is there
{"collection": "customers", "find": {"email": {"$exists": true}},
 "count": true}
{"collection": "customers", "find": {"email": {"$exists": false}},
 "projection": {"name": 1, "city": 1, "email": 1}}

// The three most expensive products
{"collection": "products", "find": {},
 "projection": {"name": 1, "price": 1},
 "sort": {"price": -1}, "limit": 3}

// Two sort keys: category first, then price high to low
{"collection": "products", "find": {"category_id": {"$lte": 2}},
 "projection": {"category_id": 1, "name": 1, "price": 1},
 "sort": {"category_id": 1, "price": -1}}

// Pages of 4 by name: page 1, then page 2 (skip 4)
{"collection": "products", "find": {},
 "projection": {"name": 1}, "sort": {"name": 1}, "limit": 4}
{"collection": "products", "find": {},
 "projection": {"_id": 0, "name": 1, "price": 1},
 "sort": {"name": 1}, "skip": 4, "limit": 4}

// How many documents match
{"collection": "products", "find": {}, "count": true}
{"collection": "orders", "find": {"status": "shipped"}, "count": true}

// The different values of a field, each once
{"collection": "orders", "find": {}, "distinct": "status"}

// distinct goes inside arrays: every tag in use
{"collection": "products", "find": {"active": true}, "distinct": "tags"}

// Distinct also takes a filter: cities of customers since 2024
{"collection": "customers", "find": {"joined": {"$gte": "2024-01-01"}},
 "distinct": "city"}

// $not negates one operator (and keeps missing fields)
{"collection": "reviews", "find": {"rating": {"$not": {"$gte": 4}}},
 "projection": {"product_id": 1, "rating": 1}}

// $nor: none of the conditions is true
{"collection": "orders",
 "find": {"$nor": [{"status": "cancelled"}, {"total": {"$lt": 12}}]},
 "projection": {"status": 1, "total": 1}, "sort": {"_id": 1}}

// $type: by the BSON type of the value
{"collection": "employees", "find": {"manager_id": {"$type": "null"}},
 "projection": {"name": 1}}

// A mixed field: some prices written as text by mistake
{"collection": "prices", "insert": [{"_id": 1, "price": 2.5},
 {"_id": 2, "price": "3,10"}, {"_id": 3, "price": 4}]}
{"collection": "prices", "find": {"price": {"$type": "string"}}}

// A single value matches any element of the array
{"collection": "products", "find": {"tags": "sweet"},
 "projection": {"name": 1, "tags": 1}, "sort": {"_id": 1}}

// A whole array matches only that exact array, in that order
{"collection": "products", "find": {"tags": ["bread", "sweet"]},
 "projection": {"name": 1}}

// $size: by the number of elements
{"collection": "products", "find": {"tags": {"$size": 0}},
 "projection": {"name": 1, "tags": 1}}

// $all: every one of these, in any order; $in: any of them
{"collection": "products", "find": {"tags": {"$all": ["sweet", "fresh"]}},
 "projection": {"name": 1}}
{"collection": "products", "find": {"tags": {"$in": ["tea", "coffee", "juice"]}},
 "projection": {"_id": 0, "name": 1, "tags": 1, "price": 1},
 "sort": {"price": 1}}

// An order carries its lines inside: an array of documents
{"collection": "orders", "find": {"_id": 2},
 "projection": {"customer_id": 1, "items": 1}}

// Dot notation reaches into the array: orders with Espresso beans (4)
{"collection": "orders", "find": {"items.product_id": 4},
 "projection": {"customer_id": 1, "total": 1}, "sort": {"_id": 1}}

// And projects only part of each line
{"collection": "orders", "find": {"_id": 1},
 "projection": {"items.product_id": 1, "items.qty": 1}}

// Orders with a line of 4 or more units
{"collection": "orders", "find": {"items.qty": {"$gte": 4}},
 "projection": {"_id": 1, "customer_id": 1, "ordered": 1, "total": 1},
 "sort": {"_id": 1}}

// Two conditions on the array... met by DIFFERENT lines
{"collection": "orders",
 "find": {"items.product_id": 1, "items.qty": {"$gte": 3}},
 "projection": {"total": 1}, "sort": {"_id": 1}}

// $elemMatch: both conditions on the SAME line
{"collection": "orders",
 "find": {"items": {"$elemMatch": {"product_id": 1, "qty": {"$gte": 3}}}},
 "projection": {"total": 1}}

// $elemMatch in the projection: only the first matching line
{"collection": "orders",
 "find": {"items.product_id": 9},
 "projection": {"customer_id": 1,
   "items": {"$elemMatch": {"product_id": 9}}},
 "sort": {"_id": 1}}

// One document: with its own _id
{"collection": "products", "insert": {"_id": 13, "name": "Rice pudding",
 "category_id": 3, "price": 2.9, "stock": 10, "active": true,
 "tags": ["sweet"]}}

// Several at once; they need not have the same fields
{"collection": "products", "insert": [
  {"_id": 14, "name": "Lemonade", "category_id": 2, "price": 2.2,
   "stock": 20, "active": true, "tags": ["juice"]},
  {"_id": 15, "name": "Muffin", "category_id": 1, "price": 1.8,
   "stock": 15, "active": true, "tags": ["sweet"], "vegan": true}
]}

// A new collection is created by its first insert
{"collection": "suppliers", "insert": {"_id": 1, "name": "Harina Sur"}}

// The products added, and the new field where it exists
{"collection": "products", "find": {"_id": {"$gte": 12}},
 "projection": {"name": 1, "price": 1, "stock": 1, "vegan": 1},
 "sort": {"_id": 1}}

// $set changes (or adds) fields; updateMany by default
{"collection": "products", "update": [{"_id": 3},
 {"$set": {"price": 2.95, "stock": 20}}]}

// $inc adds to a number: restock the fruit
{"collection": "products", "update": [{"category_id": 4},
 {"$inc": {"stock": 10}}]}

// $mul multiplies: Drinks 10 % dearer
{"collection": "products", "update": [{"category_id": 2},
 {"$mul": {"price": 1.1}}]}

// A filter that matches nothing changes nothing
{"collection": "products", "update": [{"_id": 99},
 {"$set": {"price": 1}}]}

{"collection": "products", "find": {"_id": {"$in": [3, 4, 5, 10, 11, 12]}},
 "projection": {"name": 1, "price": 1, "stock": 1}, "sort": {"_id": 1}}

// $push appends to the array
{"collection": "products", "update": [{"_id": 10},
 {"$push": {"tags": "organic"}}]}

// $addToSet only adds it if it is not there yet
{"collection": "products", "update": [{"_id": 2},
 {"$addToSet": {"tags": "sweet"}}]}
{"collection": "products", "update": [{"_id": 7},
 {"$addToSet": {"tags": "dairy"}}]}

// $push with $each: several at once
{"collection": "products", "update": [{"_id": 5},
 {"$push": {"tags": {"$each": ["hot", "organic"]}}}]}

// $pull removes every element equal to the value
{"collection": "products", "update": [{"tags": "fresh"},
 {"$pull": {"tags": "fresh"}}]}

{"collection": "products", "find": {"_id": {"$in": [2, 5, 7, 10, 11, 12]}},
 "projection": {"name": 1, "tags": 1}, "sort": {"_id": 1}}

// $unset removes a field from the document
{"collection": "products", "update": [{"active": false},
 {"$unset": {"tags": ""}}]}

// $rename changes the name of a field in every document
{"collection": "customers", "update": [{},
 {"$rename": {"joined": "since"}}]}

// Fill in the e-mail that was missing
{"collection": "customers", "update": [{"email": {"$exists": false}},
 {"$set": {"email": "pedro@example.com", "checked": "2024-07-01"}}]}

{"collection": "products", "find": {"_id": {"$in": [10, 11]}},
 "projection": {"name": 1, "tags": 1}}
{"collection": "customers", "find": {"city": "Seville"},
 "projection": {"name": 1, "email": 1, "since": 1, "checked": 1},
 "sort": {"_id": 1}}

// deleteMany: every document that matches the filter
{"collection": "reviews", "delete": {"rating": {"$lt": 3}}}
{"collection": "orders", "delete": {"status": "cancelled"}}

// A filter that matches nothing deletes nothing
{"collection": "orders", "delete": {"status": "returned"}}

// Check the filter with find (or count) before deleting
{"collection": "products", "find": {"active": false}, "count": true}
{"collection": "products", "delete": {"active": false}}

// drop removes the whole collection, indexes included
{"collection": "employees", "drop": true}

{"collection": "orders", "find": {},
 "projection": {"customer_id": 1, "status": 1, "total": 1},
 "sort": {"_id": 1}}

// In SQL an order is one row in orders plus N rows in order_items.
// Here it is one document: the lines travel with it.
{"collection": "orders", "find": {"_id": 4}}

// A new model: the address embedded, the phones as an array
{"collection": "suppliers", "insert": [
  {"_id": 1, "name": "Harina Sur", "phones": ["954000111"],
   "address": {"street": "Calle Feria 3", "city": "Seville"}},
  {"_id": 2, "name": "Lácteos Norte", "phones": ["944000222", "944000333"],
   "address": {"street": "Gran Vía 10", "city": "Bilbao"}}
]}

// Query and project inside the embedded document
{"collection": "suppliers", "find": {"address.city": "Bilbao"},
 "projection": {"name": 1, "address.city": 1}}

// The other model: reference by id, like a foreign key
{"collection": "products", "update": [{"category_id": 1},
 {"$set": {"supplier_id": 1}}]}
{"collection": "products", "find": {"supplier_id": 1},
 "projection": {"name": 1, "category_id": 1, "supplier_id": 1},
 "sort": {"_id": 1}}

// $ is the first line that matched the filter
{"collection": "orders",
 "update": [{"_id": 7, "items.product_id": 2},
 {"$set": {"items.$.qty": 8, "total": 12}}]}

// $[] is every line: order 1 at half price, total included
{"collection": "orders", "update": [{"_id": 1},
 {"$mul": {"items.$[].price": 0.5, "total": 0.5}}]}

// Add a line to an order and fix its total
{"collection": "orders", "update": [{"_id": 9},
 {"$push": {"items": {"product_id": 7, "qty": 1, "price": 1.1}},
  "$inc": {"total": 1.1}}]}

{"collection": "orders", "find": {"_id": {"$in": [1, 7, 9]}},
 "projection": {"total": 1, "items.qty": 1, "items.price": 1},
 "sort": {"_id": 1}}

// Report: what to reorder, and who has open orders

// 1. Active products with little stock, lowest first
{"collection": "products",
 "find": {"active": true, "stock": {"$lt": 15}},
 "projection": {"_id": 0, "name": 1, "stock": 1},
 "sort": {"stock": 1, "name": 1}}

// 2. How many orders are still open
{"collection": "orders", "find": {"status": {"$in": ["new", "paid"]}},
 "count": true}

// 3. Which customers they belong to
{"collection": "orders", "find": {"status": {"$in": ["new", "paid"]}},
 "distinct": "customer_id"}

// 4. The open orders, newest first, with their size
{"collection": "orders",
 "find": {"status": {"$in": ["new", "paid"]}},
 "projection": {"customer_id": 1, "ordered": 1, "status": 1, "total": 1},
 "sort": {"ordered": -1}}

advanced.code:
// A pipeline: each stage receives the documents of the one before
{"collection": "orders", "aggregate": [
  {"$match": {"status": "shipped"}},
  {"$sort": {"_id": 1}},
  {"$limit": 3},
  {"$project": {"customer_id": 1, "ordered": 1, "total": 1}}
]}

// $project shapes the output: keep, drop, rename, compute
{"collection": "orders", "aggregate": [
  {"$match": {"status": {"$ne": "cancelled"}, "total": {"$gte": 12}}},
  {"$project": {
    "_id": 0,
    "order": "$_id",
    "customer": "$customer_id",
    "date": "$ordered",
    "lines": {"$size": "$items"},
    "total": "$total"
  }},
  {"$sort": {"total": -1}}
]}

// $group: one output document per distinct _id
{"collection": "orders", "aggregate": [
  {"$group": {"_id": "$status", "orders": {"$sum": 1}}},
  {"$sort": {"_id": 1}}
]}

// _id null: the whole collection in one group
{"collection": "products", "aggregate": [
  {"$group": {"_id": null, "products": {"$sum": 1},
    "units": {"$sum": "$stock"}, "avg_price": {"$avg": "$price"}}},
  {"$addFields": {"avg_price": {"$round": ["$avg_price", 2]}}}
]}

// Per category: count, average, cheapest and dearest
{"collection": "products", "aggregate": [
  {"$group": {
    "_id": "$category_id",
    "products": {"$sum": 1},
    "avg_price": {"$avg": "$price"},
    "min_price": {"$min": "$price"},
    "max_price": {"$max": "$price"},
    "stock": {"$sum": "$stock"}
  }},
  {"$addFields": {"avg_price": {"$round": ["$avg_price", 2]}}},
  {"$sort": {"_id": 1}}
]}

// The three best customers by money spent (cancelled excluded)
{"collection": "orders", "aggregate": [
  {"$match": {"status": {"$ne": "cancelled"}}},
  {"$group": {"_id": "$customer_id", "spent": {"$sum": "$total"}}},
  {"$sort": {"spent": -1}},
  {"$limit": 3}
]}

// $count: how many documents reach this stage
{"collection": "orders", "aggregate": [
  {"$match": {"total": {"$gt": 12}}},
  {"$count": "big_orders"}
]}

// $sortByCount = $group by a value + $sum 1 + $sort descending
{"collection": "customers", "aggregate": [
  {"$sortByCount": "$city"},
  {"$sort": {"count": -1, "_id": 1}}
]}

// $unwind: one document per element of the array
{"collection": "orders", "aggregate": [
  {"$match": {"_id": 1}},
  {"$unwind": "$items"},
  {"$project": {"order": "$_id", "product": "$items.product_id",
    "qty": "$items.qty", "price": "$items.price"}}
]}

// Units and revenue per product, from every order line
{"collection": "orders", "aggregate": [
  {"$match": {"status": {"$ne": "cancelled"}}},
  {"$unwind": "$items"},
  {"$group": {
    "_id": "$items.product_id",
    "units": {"$sum": "$items.qty"},
    "revenue": {"$sum": {"$multiply": ["$items.qty", "$items.price"]}},
    "orders": {"$sum": 1}
  }},
  {"$addFields": {"revenue": {"$round": ["$revenue", 2]}}},
  {"$sort": {"revenue": -1, "_id": 1}}
]}

// $lookup: a left outer join with another collection
{"collection": "orders", "aggregate": [
  {"$match": {"_id": 3}},
  {"$lookup": {"from": "customers", "localField": "customer_id",
    "foreignField": "_id", "as": "customer"}},
  {"$project": {"total": 1, "customer.name": 1, "customer.city": 1}}
]}

// The array has one element: $unwind it and take the fields
{"collection": "orders", "aggregate": [
  {"$lookup": {"from": "customers", "localField": "customer_id",
    "foreignField": "_id", "as": "customer"}},
  {"$unwind": "$customer"},
  {"$project": {
    "_id": 0,
    "order": "$_id",
    "name": "$customer.name",
    "city": "$customer.city",
    "status": "$status",
    "total": "$total"
  }},
  {"$sort": {"order": 1}}
]}

// Order lines with the product name and its category name
{"collection": "orders", "aggregate": [
  {"$match": {"status": {"$ne": "cancelled"}}},
  {"$unwind": "$items"},
  {"$lookup": {"from": "products", "localField": "items.product_id",
    "foreignField": "_id", "as": "product"}},
  {"$unwind": "$product"},
  {"$lookup": {"from": "categories", "localField": "product.category_id",
    "foreignField": "_id", "as": "category"}},
  {"$unwind": "$category"},
  // Revenue per category, and how many different products
  {"$group": {
    "_id": "$category.name",
    "lines": {"$sum": 1},
    "units": {"$sum": "$items.qty"},
    "revenue": {"$sum": {"$multiply": ["$items.qty", "$items.price"]}},
    "products": {"$addToSet": "$product.name"}
  }},
  {"$project": {"lines": 1, "units": 1, "revenue": {"$round": ["$revenue", 2]},
    "products": {"$size": "$products"}}},
  {"$sort": {"revenue": -1}}
]}

// $addFields keeps every field and adds new ones
{"collection": "products", "aggregate": [
  {"$match": {"category_id": 3}},
  {"$addFields": {"stock_value": {"$multiply": ["$price", "$stock"]}}},
  {"$project": {"name": 1, "price": 1, "stock": 1, "stock_value": 1}}
]}

// Expressions nest: price with 21 % VAT, rounded, and margin
{"collection": "products", "aggregate": [
  {"$match": {"stock": {"$gt": 0}}},
  {"$addFields": {
    "with_vat": {"$round": [{"$multiply": ["$price", 1.21]}, 2]},
    "cost": {"$round": [{"$divide": ["$price", 1.6]}, 2]}
  }},
  {"$addFields": {"margin": {"$round": [{"$subtract": ["$price", "$cost"]}, 2]},
    "value": {"$trunc": [{"$multiply": ["$price", "$stock"]}]}}},
  {"$project": {"_id": 0, "name": 1, "price": 1, "with_vat": 1,
    "margin": 1, "value": 1}},
  {"$sort": {"value": -1}},
  {"$limit": 8}
]}

// $cond: if / then / else inside an expression
{"collection": "products", "aggregate": [
  {"$project": {"name": 1, "stock": 1,
    "reorder": {"$cond": {"if": {"$lt": ["$stock", 15]},
      "then": "yes", "else": "no"}}}},
  {"$match": {"reorder": "yes"}},
  {"$sort": {"stock": 1, "_id": 1}}
]}

// $switch: the first branch whose case is true
{"collection": "products", "aggregate": [
  {"$addFields": {"band": {"$switch": {
    "branches": [
      {"case": {"$lt": ["$price", 2]}, "then": "cheap"},
      {"case": {"$lt": ["$price", 5]}, "then": "mid"}
    ],
    "default": "premium"
  }}}},
  {"$group": {"_id": "$band", "products": {"$sum": 1},
    "from": {"$min": "$price"}, "to": {"$max": "$price"},
    // $cond inside an accumulator: count only those in stock
    "in_stock": {"$sum": {"$cond": [{"$gt": ["$stock", 0]}, 1, 0]}}}},
  {"$sort": {"from": 1}}
]}

// Join, change case, cut and measure text
{"collection": "customers", "aggregate": [
  {"$match": {"email": {"$exists": true}}},
  {"$project": {
    "_id": 0,
    "label": {"$concat": [{"$toUpper": "$city"}, " · ", "$name"]},
    "initials": {"$concat": [
      {"$substrCP": ["$name", 0, 1]},
      {"$substrCP": [{"$arrayElemAt": [{"$split": ["$name", " "]}, 1]}, 0, 1]}
    ]},
    "user": {"$arrayElemAt": [{"$split": ["$email", "@"]}, 0]},
    "length": {"$strLenCP": "$name"}
  }},
  {"$sort": {"label": 1}}
]}

// The dates are "YYYY-MM-DD" text: the first 7 characters are the month
{"collection": "orders", "aggregate": [
  {"$match": {"status": {"$ne": "cancelled"}}},
  {"$group": {
    "_id": {"$substrCP": ["$ordered", 0, 7]},
    "orders": {"$sum": 1},
    "revenue": {"$sum": "$total"},
    "first": {"$min": "$ordered"},
    "last": {"$max": "$ordered"}
  }},
  {"$sort": {"_id": 1}}
]}

// Text compares in order, so a range of dates works with $gte / $lt.
// $dateFromString turns it into a real date: the day of the week
{"collection": "orders", "aggregate": [
  {"$match": {"ordered": {"$gte": "2024-05-01", "$lt": "2024-07-01"}}},
  {"$project": {"ordered": 1, "total": 1,
    "weekday": {"$dayOfWeek": {"$dateFromString": {"dateString": "$ordered"}}},
    "days_since_may": {"$divide": [{"$subtract": [
      {"$dateFromString": {"dateString": "$ordered"}},
      {"$dateFromString": {"dateString": "2024-05-01"}}]}, 86400000]}}},
  {"$sort": {"ordered": 1}}
]}

// Work on the items array without $unwind
{"collection": "orders", "aggregate": [
  {"$match": {"status": {"$ne": "cancelled"}}},
  {"$project": {
    // $map: one value per element
    "units": {"$sum": {"$map": {"input": "$items", "as": "i",
      "in": "$$i.qty"}}},
    // $filter: only the elements that pass the condition
    "big_lines": {"$size": {"$filter": {"input": "$items", "as": "i",
      "cond": {"$gte": ["$$i.qty", 2]}}}},
    // $reduce: fold the array into one value
    "computed": {"$round": [{"$reduce": {"input": "$items",
      "initialValue": 0,
      "in": {"$add": ["$$value", {"$multiply": ["$$this.qty", "$$this.price"]}]}}}, 2]},
    "total": 1
  }},
  {"$addFields": {"ok": {"$eq": ["$computed", "$total"]}}},
  {"$sort": {"_id": 1}}
]}

// $bucket: groups by ranges you choose [0, 2) [2, 4) [4, 10)
{"collection": "products", "aggregate": [
  {"$bucket": {
    "groupBy": "$price",
    "boundaries": [0, 2, 4, 10],
    "default": "other",
    "output": {
      "products": {"$sum": 1},
      "stock": {"$sum": "$stock"},
      "names": {"$push": "$name"}
    }
  }},
  {"$project": {"products": 1, "stock": 1,
    "first": {"$arrayElemAt": ["$names", 0]}}}
]}

// $bucketAuto: you say how many, MongoDB picks the ranges
{"collection": "orders", "aggregate": [
  {"$bucketAuto": {"groupBy": "$total", "buckets": 3,
    "output": {"orders": {"$sum": 1}, "avg": {"$avg": "$total"}}}},
  {"$project": {"_id": 0, "from": "$_id.min", "to": "$_id.max",
    "orders": 1, "avg": {"$round": ["$avg", 2]}}}
]}

// $facet: several pipelines over the same input, in one query
{"collection": "products", "aggregate": [
  {"$match": {"active": true}},
  {"$facet": {
    "by_category": [
      {"$group": {"_id": "$category_id", "n": {"$sum": 1}}},
      {"$sort": {"_id": 1}}
    ],
    "top_price": [
      {"$sort": {"price": -1}}, {"$limit": 1},
      {"$project": {"_id": 0, "name": 1, "price": 1}}
    ],
    "totals": [
      {"$group": {"_id": null, "products": {"$sum": 1},
        "stock": {"$sum": "$stock"}}}
    ]
  }},
  // Each facet is an array: pick values out to get a flat row
  {"$project": {
    "categories": {"$size": "$by_category"},
    "products": {"$arrayElemAt": ["$totals.products", 0]},
    "stock": {"$arrayElemAt": ["$totals.stock", 0]},
    "dearest": {"$arrayElemAt": ["$top_price.name", 0]},
    "price": {"$arrayElemAt": ["$top_price.price", 0]}
  }}
]}

// $graphLookup follows a reference again and again:
// from each employee up through manager_id to the top
{"collection": "employees", "aggregate": [
  {"$match": {"_id": 3}},
  {"$graphLookup": {"from": "employees", "startWith": "$manager_id",
    "connectFromField": "manager_id", "connectToField": "_id",
    "as": "bosses", "depthField": "level"}},
  {"$unwind": "$bosses"},
  {"$project": {"_id": 0, "boss": "$bosses.name", "level": {"$toInt": "$bosses.level"}}},
  {"$sort": {"level": 1}}
]}

// Downwards: everyone under each person, at any depth
{"collection": "employees", "aggregate": [
  {"$graphLookup": {"from": "employees", "startWith": "$_id",
    "connectFromField": "_id", "connectToField": "manager_id",
    "as": "team", "depthField": "depth"}},
  {"$project": {
    "name": 1,
    "role": 1,
    "team": {"$size": "$team"},
    "direct": {"$size": {"$filter": {"input": "$team", "as": "t",
      "cond": {"$eq": ["$$t.depth", 0]}}}},
    "payroll": {"$add": ["$salary", {"$sum": "$team.salary"}]}
  }},
  {"$sort": {"team": -1, "_id": 1}}
]}

// $lookup with let + pipeline: the joined side has its own stages
{"collection": "products", "aggregate": [
  {"$lookup": {
    "from": "reviews",
    "let": {"pid": "$_id"},
    "pipeline": [
      {"$match": {"$expr": {"$eq": ["$product_id", "$$pid"]}}},
      {"$group": {"_id": null, "n": {"$sum": 1},
        "avg": {"$avg": "$rating"}, "low": {"$min": "$rating"}}}
    ],
    "as": "stats"
  }},
  // Without reviews the array is empty: keep only those that have some
  {"$unwind": "$stats"},
  {"$project": {"_id": 0, "name": 1,
    "reviews": "$stats.n",
    "rating": {"$round": ["$stats.avg", 1]},
    "worst": "$stats.low"}},
  {"$sort": {"rating": -1, "name": 1}}
]}

