// unique: no two customers may share an e-mail
{"collection": "customers", "createIndex": {"email": 1}, "unique": true,
 "name": "email_unique"}
{"collection": "customers", "indexes": true}

// Sign-ups arrive in a staging collection
{"collection": "signups", "insert": [
  {"_id": 9, "name": "Iris Vega", "email": "iris@example.com",
   "city": "Madrid", "joined": "2024-06-10"},
  {"_id": 10, "name": "Ana G.", "email": "ana@example.com",
   "city": "Madrid", "joined": "2024-06-11"}]}

// $merge copies them into customers: a new e-mail goes in...
{"collection": "signups", "aggregate": [
  {"$match": {"_id": 9}},
  {"$merge": {"into": "customers", "whenNotMatched": "insert"}}]}
{"collection": "customers", "find": {"_id": {"$gte": 8}},
 "projection": {"name": 1, "email": 1}, "sort": {"_id": 1}}

// ...but an e-mail that is already there breaks the unique index
{"collection": "signups", "aggregate": [
  {"$match": {"_id": 10}},
  {"$merge": {"into": "customers", "whenNotMatched": "insert"}}]}

// $out writes the result into a collection (replacing it)
{"collection": "orders", "aggregate": [
  {"$match": {"status": {"$ne": "cancelled"}}},
  {"$group": {"_id": "$customer_id", "orders": {"$sum": 1},
    "spent": {"$sum": "$total"}}},
  {"$out": "customer_stats"}
]}

// A new order for customer 8, and one more for customer 1
{"collection": "orders", "insert": [
  {"_id": 11, "customer_id": 8, "ordered": "2024-06-09", "status": "paid",
   "total": 7.75, "items": [{"product_id": 9, "qty": 1, "price": 7.75}]},
  {"_id": 12, "customer_id": 1, "ordered": "2024-06-10", "status": "new",
   "total": 4.5, "items": [{"product_id": 5, "qty": 1, "price": 4.5}]}]}

// $merge upserts: updates the ones that exist, inserts the rest
{"collection": "orders", "aggregate": [
  {"$match": {"_id": {"$gt": 10}}},
  {"$group": {"_id": "$customer_id", "orders": {"$sum": 1},
    "spent": {"$sum": "$total"}}},
  {"$merge": {"into": "customer_stats", "on": "_id",
    "whenMatched": [{"$set": {
      "orders": {"$add": ["$orders", "$$new.orders"]},
      "spent": {"$add": ["$spent", "$$new.spent"]}}}],
    "whenNotMatched": "insert"}}
]}

{"collection": "customer_stats", "find": {}, "sort": {"_id": 1}}

// Order lines EMBED the price paid: a copy, frozen at order time.
// They REFERENCE the product by id: name and price live in products.
{"collection": "products", "update": [{"_id": 1}, {"$set": {"price": 1.35}}]}
{"collection": "products", "update": [{"_id": 8},
 {"$set": {"name": "Greek yogurt 500 g"}}]}

// The embedded copy keeps the old price; the reference sees the new name
{"collection": "orders", "aggregate": [
  {"$unwind": "$items"},
  {"$match": {"items.product_id": {"$in": [1, 8]}}},
  {"$lookup": {"from": "products", "localField": "items.product_id",
    "foreignField": "_id", "as": "p"}},
  {"$unwind": "$p"},
  {"$project": {
    "_id": 0,
    "order": "$_id",
    "product": "$p.name",
    "paid": "$items.price",
    "today": "$p.price",
    "diff": {"$round": [{"$subtract": ["$p.price", "$items.price"]}, 2]}
  }},
  {"$sort": {"order": 1, "product": 1}}
]}

// Dashboard: one row per customer with everything a manager asks for
{"collection": "customers", "aggregate": [
  {"$lookup": {"from": "orders", "localField": "_id",
    "foreignField": "customer_id", "as": "orders"}},
  {"$addFields": {"valid": {"$filter": {"input": "$orders", "as": "o",
    "cond": {"$ne": ["$$o.status", "cancelled"]}}}}},
  {"$project": {
    "_id": 0,
    "customer": "$name",
    "city": "$city",
    "orders": {"$size": "$valid"},
    "spent": {"$round": [{"$sum": "$valid.total"}, 2]},
    "last": {"$max": "$valid.ordered"},
    "tier": {"$switch": {"branches": [
      {"case": {"$gte": [{"$sum": "$valid.total"}, 30]}, "then": "gold"},
      {"case": {"$gte": [{"$sum": "$valid.total"}, 15]}, "then": "silver"}],
      "default": "bronze"}}
  }},
  {"$sort": {"spent": -1, "customer": 1}}
]}
